const DICTS = { en, ar };
let current = 'en';

export function locale() { return current; }

export function setLocale(l) {
  current = DICTS[l] ? l : 'en';
  document.documentElement.lang = current;
  document.documentElement.dir = current === 'ar' ? 'rtl' : 'ltr';
  document.title = DICTS[current]['app.name'];
  const skip = document.getElementById('skip-link');
  if (skip) skip.textContent = current === 'ar' ? 'انتقل إلى المحتوى' : 'Skip to content';
  try { localStorage.setItem('cs-locale', current); } catch { /* preference is optional */ }
}

/** Account preference wins, then the last choice on this device, then the browser language. */
export function initLocale(accountLocale) {
  let saved = null;
  try { saved = localStorage.getItem('cs-locale'); } catch { saved = null; }
  setLocale(accountLocale || saved || (navigator.language?.startsWith('ar') ? 'ar' : 'en'));
}

export function hasKey(key) { return key in DICTS[current] || key in en; }

export function t(key, params) {
  let s = DICTS[current][key] ?? en[key] ?? key;
  if (params) s = s.replace(/\{(\w+)\}/g, (_, k) => (params[k] ?? `{${k}}`));
  return s;
}

/**
 * Built-in data shown in the interface language while it still has its shipped English text
 * (a plan's description); text an administrator has changed is shown as written.
 */
export function shipped(key, text) { return en[key] === text ? t(key) : text; }

export const _dicts = DICTS;
